from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending_at = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending_at[b].append((a, idx))

        gains = [0] * len(conflictingPairs)
        best_left = 0
        second_left = 0
        best_count = 0
        best_id = -1
        total = 0

        for right in range(1, n + 1):
            for left, idx in ending_at[right]:
                if left > best_left:
                    second_left = best_left
                    best_left = left
                    best_count = 1
                    best_id = idx
                elif left == best_left:
                    best_count += 1
                else:
                    second_left = max(second_left, left)

            total += right - best_left

            if best_count == 1:
                gains[best_id] += best_left - second_left

        return total + max(gains)
