import sys

MOD = 998244353

def fwht(a, mod=None):
    n = len(a)
    h = 1
    while h < n:
        for i in range(0, n, h << 1):
            e = i + h
            for j in range(i, e):
                x, y = a[j], a[j + h]
                if mod is None:
                    a[j] = x + y
                    a[j + h] = x - y
                else:
                    a[j] = (x + y) % mod
                    a[j + h] = (x - y) % mod
        h <<= 1

def main():
    input = sys.stdin.readline
    N, M, K = map(int, input().split())
    A = list(map(int, input().split()))
    U = 1 << 20

    freq = [0] * U
    for x in A:
        freq[x] += 1
    fwht(freq)

    inv = [0] * (N + 1)
    if N >= 1:
        inv[1] = 1
    for i in range(2, N + 1):
        inv[i] = MOD - MOD // i * inv[MOD % i] % MOD

    p = [0] * M
    comb = 1
    for j in range(N + 1):
        p[j % M] = (p[j % M] + comb) % MOD
        if j < N:
            comb = comb * (N - j) % MOD * inv[j + 1] % MOD

    coeff = [0] * (N + 1)
    coeff[0] = p[0]
    inv2 = (MOD + 1) // 2
    invm = pow(M, MOD - 2, MOD)
    pow2n = pow(2, N, MOD)

    for q in range(1, N + 1):
        d = [0] * M
        prev = p[-1]
        for j in range(M):
            d[j] = (p[j] - prev) % MOD
            prev = p[j]

        np = [0] * M
        if M & 1:
            s = d[0]
            for j in range(1, M):
                if j & 1:
                    s -= d[j]
                else:
                    s += d[j]
            np[0] = (s % MOD) * inv2 % MOD
        else:
            v = 0
            for j in range(1, M):
                if j & 1:
                    v -= (M - j) * d[j]
                else:
                    v += (M - j) * d[j]
            target = pow2n if q == N else 0
            np[0] = (target - v) % MOD * invm % MOD

        for j in range(1, M):
            np[j] = (d[j] - np[j - 1]) % MOD
        p = np
        coeff[q] = p[0]

    weight = [pow(x, K, MOD) for x in range(U)]
    fwht(weight, MOD)

    ans = 0
    for s in range(U):
        q = (N - freq[s]) // 2
        ans += weight[s] * coeff[q]
    print(ans % MOD * pow(U, MOD - 2, MOD) % MOD)

if __name__ == "__main__":
    main()
```
